import "./Contactus.css";


export default class Contactus extends Component {
    render() {
        return(

    <div c="content-container">
    <div c="rectangle">
    <h1><a c="contact">Contact Us</a></h1>
    <p c="foryou">We are here for you!</p>
    <p c="na1">Name:</p>
    <input c="Name"></input>
    <p c="na1">Email:</p>
    <input c="Name"></input>
    <p c="na1">Message:</p>
    <input c="message"></input>
    <p c="sendmail">you can also send to our mail: TaiLink@gmail.com</p>
    <button type="button" c="button">send</button>
   </div>
   </div>



      );
    }     
}
